import numpy as np

def Bspline(xi, i, p, Xi):
    if p == 0:
        return np.array([1 if Xi[xi] <= t < Xi[xi+1] else 0 for t in [Xi[xi], Xi[xi+1], Xi[xi+2] if len(Xi) > xi+2 else np.inf]])[0]
    else:
        t1 = (Xi[xi+p+1] - Xi[xi]) / (Xi[xi+p+1] - Xi[xi+1]) if Xi[xi+p+1]!= Xi[xi+1] else 0
        t2 = (Xi[xi+1] - Xi[xi]) / (Xi[xi+p+1] - Xi[xi+1]) if Xi[xi+p+1]!= Xi[xi+1] else 1
        alpha = (t1 if Xi[xi] <= Xi[xi+p+1] else 0) if Xi[xi] <= Xi[xi+1] else 0
        beta = (t2 if Xi[xi+1] <= Xi[xi+p+1] else 0) if Xi[xi+1] <= Xi[xi+p+1] else 0
        return alpha * Bspline(xi, i, p-1, Xi) + beta * Bspline(xi+1, i, p-1, Xi)
