import numpy as np

def NURBS_2D(xi_1, xi_2, i_1, i_2, p_1, p_2, n_1, n_2, Xi_1, Xi_2, w):
    def NURBS_basis(xi, i, p, Xi, w):
        if p == 0:
            return np.array([w[i] if Xi[i] <= t < Xi[i+1] else 0 for t in [Xi[i], Xi[i+1], Xi[i+2] if len(Xi) > i+2 else np.inf]])[0]
        else:
            t1 = (Xi[i+p+1] - Xi[i]) / (Xi[i+p+1] - Xi[i+1]) if Xi[i+p+1]!= Xi[i+1] else 0
            t2 = (Xi[i+1] - Xi[i]) / (Xi[i+p+1] - Xi[i+1]) if Xi[i+p+1]!= Xi[i+1] else 1
            alpha = (t1 if Xi[i] <= Xi[i+p+1] else 0) if Xi[i] <= Xi[i+1] else 0
            beta = (t2 if Xi[i+1] <= Xi[i+p+1] else 0) if Xi[i+1] <= Xi[i+p+1] else 0
            return alpha * NURBS_basis(xi, i, p-1, Xi, w) + beta * NURBS_basis(xi, i+1, p-1, Xi, w)

    N_1 = NURBS_basis(xi_1, i_1, p_1, Xi_1, w)
    N_2 = NURBS_basis(xi_2, i_2, p_2, Xi_2, w)

    denominator = sum(NURBS_basis(xi_1, j, p_1, Xi_1, w) * NURBS_basis(xi_2, k, p_2, Xi_2, w) * w[j*n_2 + k] for j in range(n_1) for k in range(n_2))

    R_1 = N_1 * N_2 * w[i_1*n_2 + i_2] / denominator
    R_2 = N_2 * N_1 * w[i_2*n_1 + i_1] / denominator

    return np.array([R_1, R_2])
