def check_G_feasibility(G, D):
    N, R = G.shape
    A = G.T  # Transpose G to get the matrix A
    ones_vector = np.ones(N)

    # Solve the system A * t = log(D) * ones_vector
    try:
        t = np.linalg.solve(A, np.log(D) * ones_vector)
    except np.linalg.LinAlgError:
        return False

    # Check if all t_i's are positive
    if np.all(t > 0):
        return True
    else:
        return False
